-- Patrimônio+ | Catálogo Geral v1.6.0
-- Base oficial conferida em 16/10/2026.
-- 821 itens: 814 SIGEM + 7 Catálogo Próprio HRPP.
-- Classificação oficial: 582 Equipamento Médico, 199 Mobiliário, 40 Informática.

BEGIN;

ALTER TABLE descricoes_padrao ADD COLUMN IF NOT EXISTS origem_catalogo text;
ALTER TABLE descricoes_padrao ADD COLUMN IF NOT EXISTS fonte_valor text;
ALTER TABLE descricoes_padrao ADD COLUMN IF NOT EXISTS atualizado_em timestamptz NOT NULL DEFAULT now();

UPDATE descricoes_padrao
SET origem_catalogo=coalesce(origem_catalogo,'SIGEM'),
    fonte_valor=coalesce(fonte_valor,'SIGEM');

ALTER TABLE descricoes_padrao ALTER COLUMN origem_catalogo SET DEFAULT 'SIGEM';
ALTER TABLE descricoes_padrao ALTER COLUMN origem_catalogo SET NOT NULL;
ALTER TABLE descricoes_padrao ALTER COLUMN fonte_valor SET DEFAULT 'SIGEM';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='descricoes_padrao_origem_catalogo_chk') THEN
    ALTER TABLE descricoes_padrao
      ADD CONSTRAINT descricoes_padrao_origem_catalogo_chk
      CHECK (origem_catalogo IN ('SIGEM','PROPRIO'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='descricoes_padrao_fonte_valor_chk') THEN
    ALTER TABLE descricoes_padrao
      ADD CONSTRAINT descricoes_padrao_fonte_valor_chk
      CHECK (fonte_valor IS NULL OR fonte_valor IN ('SIGEM','COTACAO_PROPRIA','NOTA_FISCAL','OUTRA'));
  END IF;
END $$;

CREATE TEMP TABLE tmp_catalogo_oficial_20261016 (
  id_existente uuid,
  descricao text NOT NULL,
  valor_padrao numeric,
  tipo_id integer NOT NULL CHECK (tipo_id IN (1,2,3)),
  origem text NOT NULL CHECK (origem IN ('SIGEM','PROPRIO'))
) ON COMMIT DROP;


DO $$
BEGIN
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016) <> 821 THEN RAISE EXCEPTION 'Base oficial deve conter 821 itens'; END IF;
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016 WHERE origem='SIGEM') <> 814 THEN RAISE EXCEPTION 'Base oficial deve conter 814 itens SIGEM'; END IF;
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016 WHERE origem='PROPRIO') <> 7 THEN RAISE EXCEPTION 'Base oficial deve conter 7 itens próprios'; END IF;
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016 WHERE tipo_id=1) <> 582 THEN RAISE EXCEPTION 'Quantidade Tipo 1 divergente'; END IF;
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016 WHERE tipo_id=2) <> 199 THEN RAISE EXCEPTION 'Quantidade Tipo 2 divergente'; END IF;
  IF (SELECT count(*) FROM tmp_catalogo_oficial_20261016 WHERE tipo_id=3) <> 40 THEN RAISE EXCEPTION 'Quantidade Tipo 3 divergente'; END IF;
  IF EXISTS (
    SELECT 1 FROM tmp_catalogo_oficial_20261016 t
    LEFT JOIN descricoes_padrao d ON d.id=t.id_existente
    WHERE t.origem='SIGEM' AND (d.id IS NULL OR d.descricao IS DISTINCT FROM t.descricao)
  ) THEN RAISE EXCEPTION 'O catálogo SIGEM atual não corresponde à base oficial esperada'; END IF;
END $$;

UPDATE descricoes_padrao d
SET tipo_id=t.tipo_id,
    valor_padrao=t.valor_padrao,
    origem_catalogo='SIGEM',
    fonte_valor='SIGEM',
    ativo=true,
    atualizado_em=now()
FROM tmp_catalogo_oficial_20261016 t
WHERE t.origem='SIGEM' AND d.id=t.id_existente;

SELECT t.descricao,t.valor_padrao,t.tipo_id,true,'PROPRIO',
       CASE WHEN t.valor_padrao IS NULL THEN NULL ELSE 'COTACAO_PROPRIA' END,
       now()
FROM tmp_catalogo_oficial_20261016 t
WHERE t.origem='PROPRIO'
  AND NOT EXISTS (
    SELECT 1 FROM descricoes_padrao d
    WHERE lower(btrim(d.descricao))=lower(btrim(t.descricao))
  );

DO $$
BEGIN
  IF (SELECT count(*) FROM descricoes_padrao WHERE origem_catalogo='SIGEM') <> 814 THEN RAISE EXCEPTION 'Pós-migração: quantidade SIGEM divergente'; END IF;
  IF (SELECT count(*) FROM descricoes_padrao WHERE origem_catalogo='PROPRIO') <> 7 THEN RAISE EXCEPTION 'Pós-migração: quantidade própria divergente'; END IF;
  IF (SELECT count(*) FROM descricoes_padrao WHERE tipo_id=1) <> 582 THEN RAISE EXCEPTION 'Pós-migração: Tipo 1 divergente'; END IF;
  IF (SELECT count(*) FROM descricoes_padrao WHERE tipo_id=2) <> 199 THEN RAISE EXCEPTION 'Pós-migração: Tipo 2 divergente'; END IF;
  IF (SELECT count(*) FROM descricoes_padrao WHERE tipo_id=3) <> 40 THEN RAISE EXCEPTION 'Pós-migração: Tipo 3 divergente'; END IF;
  IF EXISTS (SELECT 1 FROM descricoes_padrao WHERE origem_catalogo NOT IN ('SIGEM','PROPRIO')) THEN RAISE EXCEPTION 'Origem inválida'; END IF;
END $$;

COMMIT;

SELECT
  'CATALOGO_GERAL_160_OK' AS resultado,
  count(*)::int AS total,
  count(*) FILTER (WHERE origem_catalogo='SIGEM')::int AS sigem,
  count(*) FILTER (WHERE origem_catalogo='PROPRIO')::int AS proprio,
  count(*) FILTER (WHERE tipo_id=1)::int AS equipamento_medico,
  count(*) FILTER (WHERE tipo_id=2)::int AS mobiliario,
  count(*) FILTER (WHERE tipo_id=3)::int AS informatica
FROM descricoes_padrao;
